-- ============================================================================
-- SEED — campos de site do escore (linguagem leiga). Gerado 2026-06-05.
-- (1) transporte patient_explanation→site_explanation/site_legend; (2) inferência de
-- site_render_type; (3) os 3 níveis residuais; (4) [abaixo] conteúdo leigo gerado item a
-- item por workflow (70 agentes Claude). Idempotente (guardas IS NULL). Para levar a prod.
-- ============================================================================
BEGIN;
UPDATE score_items SET site_explanation = patient_explanation
  WHERE deleted_at IS NULL AND site_explanation IS NULL AND patient_explanation IS NOT NULL AND patient_explanation <> '';
UPDATE score_levels SET site_legend = patient_explanation
  WHERE deleted_at IS NULL AND site_legend IS NULL AND patient_explanation IS NOT NULL AND patient_explanation <> '';
UPDATE score_items si SET site_render_type = CASE
  WHEN si.lab_test_code IS NOT NULL THEN 'numeric_classifier'
  WHEN si.unit IS NOT NULL AND si.unit <> '' AND EXISTS (SELECT 1 FROM score_levels sl WHERE sl.item_id=si.id AND sl.deleted_at IS NULL) THEN 'numeric_classifier'
  WHEN (SELECT count(*) FROM score_levels sl WHERE sl.item_id=si.id AND sl.deleted_at IS NULL) = 2 THEN 'boolean'
  WHEN EXISTS (SELECT 1 FROM score_levels sl WHERE sl.item_id=si.id AND sl.deleted_at IS NULL) THEN 'level_choice'
  ELSE 'text' END
  WHERE si.deleted_at IS NULL AND si.site_render_type IS NULL;
UPDATE score_levels SET site_legend='Espessura do endométrio dentro do normal para a pós-menopausa.' WHERE id='019bf31d-2ef0-7e3d-b662-88aee789e45a' AND site_legend IS NULL;
UPDATE score_levels SET site_legend='Perfil genético de alto risco para doença celíaca.' WHERE id='019bfee6-cd07-7eb2-84a8-d11bd7bb9134' AND site_legend IS NULL;
UPDATE score_levels SET site_legend='Diarreia intensa e ativa no momento.' WHERE id='019bf7af-d85e-7c01-9de0-14a37fceb663' AND site_legend IS NULL;
COMMIT;
